abstract class ConvertWikiTask @Inject constructor(objects: ObjectFactory) : JavaExec() {
    @get:InputFiles
    @get:PathSensitive(PathSensitivity.RELATIVE)
    val wikiXmlInput: ConfigurableFileCollection = objects.fileCollection()

    @get:Input
    abstract val wikiInputFormat: Property<String>

    @get:OutputFile
    abstract val wikiBinaryOutput: RegularFileProperty

    @get:Input
    abstract val wikiOutputFormat: Property<String>

    @get:Optional
    @get:InputFiles
    @get:PathSensitive(PathSensitivity.RELATIVE)
    val wikiIndexInput: ConfigurableFileCollection = objects.fileCollection()

    @get:Input
    abstract val wikiNoIndex: Property<Boolean>

    override fun exec() {
        val input = wikiXmlInput.singleFile
        val output = wikiBinaryOutput.get().asFile
        val indexFiles = wikiIndexInput.files
        require(indexFiles.size <= 1) {
            "wikiIndexInput must contain at most one file"
        }
        val index = indexFiles.singleOrNull()

        require(input.exists()) {
            "wikiXmlInput does not exist: ${input.path}. Pass -PwikiXmlInput=<file-or-directory>."
        }
        require(index == null || index.exists()) {
            "wikiIndexInput does not exist: ${index?.path}"
        }

        output.parentFile?.mkdirs()
        if (output.exists()) {
            output.delete()
        }

        val convertArgs = mutableListOf(
            "convert",
            "--input", input.path,
            "--input-format", wikiInputFormat.get(),
            "--output", output.path,
            "--output-format", wikiOutputFormat.get()
        )
        if (index != null) {
            convertArgs.addAll(listOf("--index", index.path))
        }
        if (wikiNoIndex.get()) {
            convertArgs.add("--no-index")
        }
        setArgs(convertArgs)

        super.exec()
    }
}

