tasks.named<com.github.jengelman.gradle.plugins.shadow.tasks.ShadowJar>("shadowJar") {
    archiveFileName.set("wikilinks.jar")
    manifest {
        attributes["Main-Class"] = "fi.eonwe.wikilinks.Main"
    }
}

tasks.named("build") {
    dependsOn(tasks.named("shadowJar"))
}

tasks.named("startScripts") {
    dependsOn(tasks.named("shadowJar"))
}

tasks.named<Jar>("jar") {
    archiveFileName.set("wikilinks-thin.jar")
}

tasks.named("startShadowScripts") {
    dependsOn(tasks.named("shadowJar"))
    dependsOn(tasks.named("jar"))
}

val wikiXmlInputPath = providers.gradleProperty("wikiXmlInput").orElse("data/wiki.xml.bz2")
val wikiInputFormatName = providers.gradleProperty("wikiInputFormat").orElse("xml")
val wikiBinaryOutputPath = providers.gradleProperty("wikiBinaryOutput").orElse("build/wikis/wiki.segment")
val wikiOutputFormatName = providers.gradleProperty("wikiOutputFormat").orElse("segment")
val wikiIndexInputPath = providers.gradleProperty("wikiIndexInput")
val wikiNoIndexFlag = providers.gradleProperty("wikiNoIndex")
    .map { it.toBooleanStrictOrNull() ?: error("wikiNoIndex must be true or false") }
    .orElse(false)
val wikiConvertMaxHeap = providers.gradleProperty("wikiConvertMaxHeap").orElse("4g")

tasks.register<ConvertWikiTask>("convertWiki") {
    group = "wikilinks"
    description = "Convert a Wikimedia XML dump to a Wikilinks binary graph."
    classpath = sourceSets.main.get().runtimeClasspath
    mainClass.set(application.mainClass)
    maxHeapSize = wikiConvertMaxHeap.get()
    wikiXmlInput.from(wikiXmlInputPath)
    wikiInputFormat.set(wikiInputFormatName)
    wikiBinaryOutput.set(layout.projectDirectory.file(wikiBinaryOutputPath))
    wikiOutputFormat.set(wikiOutputFormatName)
    if (wikiIndexInputPath.isPresent) {
        wikiIndexInput.from(wikiIndexInputPath)
    }
    wikiNoIndex.set(wikiNoIndexFlag)
}


